CREATE TABLE IF NOT EXISTS user_roles (user_id TEXT PRIMARY KEY,role TEXT NOT NULL);
INSERT INTO user_roles(user_id,role) SELECT id,'admin' FROM users WHERE username='admin' ON CONFLICT(user_id) DO NOTHING;
CREATE TABLE IF NOT EXISTS api_tokens (id TEXT PRIMARY KEY,name TEXT NOT NULL,prefix TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,scope TEXT NOT NULL,created_at DOUBLE PRECISION NOT NULL,expires_at DOUBLE PRECISION NOT NULL,last_used_at DOUBLE PRECISION NOT NULL,revoked INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notification_channels (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,secret TEXT NOT NULL,enabled INTEGER NOT NULL,created_at DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS alert_rules (id TEXT PRIMARY KEY,name TEXT NOT NULL,definition TEXT NOT NULL,enabled INTEGER NOT NULL,created_at DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS alert_states (rule_id TEXT PRIMARY KEY,state TEXT NOT NULL,value DOUBLE PRECISION,since_at DOUBLE PRECISION NOT NULL,checked_at DOUBLE PRECISION NOT NULL,detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notification_inbox (id TEXT PRIMARY KEY,title TEXT NOT NULL,message TEXT NOT NULL,state TEXT NOT NULL,created_at DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS notification_outbox (id TEXT PRIMARY KEY,channel_id TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL,next_attempt DOUBLE PRECISION NOT NULL,created_at DOUBLE PRECISION NOT NULL,last_error TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS outbox_pending ON notification_outbox(status,next_attempt);
CREATE TABLE IF NOT EXISTS worker_heartbeat (id TEXT PRIMARY KEY,updated_at DOUBLE PRECISION NOT NULL);
